    Write-Host ""
    Write-Host "Ajout des fichiers a git..." -ForegroundColor Cyan
    git add lib/cart-context.tsx components/cart-button.tsx components/add-to-cart-button.tsx components/cart-page-client.tsx components/products.tsx components/product-purchase-actions.tsx components/site-header.tsx app/layout.tsx app/panier/page.tsx "app/produit/[slug]/page.tsx"

    Write-Host "Creation du commit..." -ForegroundColor Cyan
    git commit -m "Ajout du panier multi-produits (ajout, quantites, commande groupee WhatsApp)"

    Write-Host "Envoi vers le depot distant..." -ForegroundColor Cyan
    git push

    Write-Host ""
    Write-Host "Termine ! Vercel va deployer automatiquement les changements." -ForegroundColor Green
} else {
    Write-Host ""
    Write-Host "Les fichiers ont ete ecrits mais AUCUN commit n'a ete fait." -ForegroundColor Yellow
    Write-Host "Pour committer plus tard, executez :" -ForegroundColor Yellow
    Write-Host "  git add ."
    Write-Host "  git commit -m ""Ajout du panier multi-produits"""
    Write-Host "  git push"
}
